const clean = (name) => $(name).all().map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
return [{
  json: {
    transactions: clean('Get Transactions'),
    budgets: clean('Get Budgets'),
    goals: clean('Get Goals'),
    serverTime: new Date().toISOString(),
  },
}];

const b = ($input.first().json.body) || {};
const entity = String(b.entity || '');
const op = String(b.op || '');
const route = entity + ':' + op;
let rows = Array.isArray(b.data) ? b.data : [b.data || {}];
if (rows.length === 0) rows = [{}];
rows = rows.slice(0, 2000);
const today = new Date().toISOString().slice(0, 10);
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
const num = (v) => { const n = Number(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : 0; };
const str = (v, d, max) => { const s = (v == null || v === '') ? d : String(v); return s.slice(0, max || 200); };
return rows.map((d) => ({
  json: {
    route,
    id: Number(b.id || d.id || 0),
    description: str(d.description, 'Untitled', 200),
    amount: Math.round(Math.abs(num(d.amount)) * 100) / 100,
    txn_type: d.txn_type === 'income' ? 'income' : 'expense',
    category: str(d.category, 'Other', 60),
    account: str(d.account, 'Main account', 60),
    txn_date: isDate(d.txn_date) ? d.txn_date : today,
    notes: str(d.notes, '', 500),
    recurring: d.recurring === true || d.recurring === 'true',
    monthly_limit: Math.abs(num(d.monthly_limit)),
    goal_name: str(d.goal_name, 'New goal', 100),
    target_amount: Math.abs(num(d.target_amount)),
    saved_amount: Math.abs(num(d.saved_amount)),
    target_date: isDate(d.target_date) ? d.target_date : '',
    color: str(d.color, '#8b5cf6', 20),
  },
}));
